using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class WeatherTools
{
    [McpServerTool(Name = "get_forecast", ReadOnly = true),
     Description("Gets a weather forecast for the given latitude and longitude.")]
    public async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m&temperature_unit=fahrenheit";

        var response = await client.GetFromJsonAsync<ForecastResponse>(url)
            ?? throw new InvalidOperationException("Empty response from weather API.");

        return $"Temperature: {response.Current.Temperature}°F, "
             + $"Wind: {response.Current.WindSpeed} mph";
    }

    [McpServerTool(Name = "get_alerts", ReadOnly = true),
     Description("Lists currently active weather alert headlines for a US state.")]
    public async Task<string> GetAlerts(
        IHttpClientFactory httpClientFactory,
        [Description("Two-letter US state code, e.g. CA")] string state)
    {
        using var client = new HttpClient();
        client.DefaultRequestHeaders.UserAgent.ParseAdd("McpServer/1.0");

        var url = $"https://api.weather.gov/alerts/active?area={state}";
        var response = await client.GetFromJsonAsync<AlertResponse>(url)
            ?? throw new InvalidOperationException("Empty response from alerts API.");

        if (response.Features.Count == 0)
            return $"No active alerts for {state}.";

        var headlines = response.Features
            .Select(f => $"• {f.Properties.Headline}")
            .Take(5);

        return string.Join("\n", headlines);
    }
}

// --- JSON models for deserialization ---

public sealed class ForecastResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather Current { get; set; } = new();
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; set; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; set; }
}

public sealed class AlertResponse
{
    [JsonPropertyName("features")]
    public List<AlertFeature> Features { get; set; } = [];
}

public sealed class AlertFeature
{
    [JsonPropertyName("properties")]
    public AlertProperties Properties { get; set; } = new();
}

public sealed class AlertProperties
{
    [JsonPropertyName("headline")]
    public string Headline { get; set; } = "";
}

