             ?? throw new InvalidOperationException("Empty response from alerts API.");

         if (response.Features.Count == 0)
             return $"No active alerts for {state}.";

         var headlines = response.Features
             .Select(f => $"• {f.Properties.Headline}")
             .Take(5);

         return string.Join("\n", headlines);
     }
 }

 // --- JSON models for deserialization ---

 public sealed class ForecastResponse
 {
     [JsonPropertyName("current")]
     public CurrentWeather Current { get; set; } = new();
 }

 public sealed class CurrentWeather
 {
     [JsonPropertyName("temperature_2m")]
     public double Temperature { get; set; }

     [JsonPropertyName("wind_speed_10m")]
     public double WindSpeed { get; set; }
 }

 public sealed class AlertResponse
 {
     [JsonPropertyName("features")]
     public List<AlertFeature> Features { get; set; } = [];
 }

 public sealed class AlertFeature
 {
     [JsonPropertyName("properties")]
     public AlertProperties Properties { get; set; } = new();
 }

 public sealed class AlertProperties
 {
     [JsonPropertyName("headline")]
     public string Headline { get; set; } = "";
 }
